CREATE MATERIALIZED VIEW IF NOT EXISTS cagg_market_hourly WITH(timescaledb.continuous)AS SELECT market_id,time_bucket(INTERVAL'1 hour',observed_at)bucket,last(supply_apr,observed_at)supply_apr,last(borrow_apr,observed_at)borrow_apr,last(fixed_apy,observed_at)fixed_apy,last(implied_apy,observed_at)implied_apy,last(underlying_apy,observed_at)underlying_apy,last(liquidity_usd,observed_at)liquidity_usd,last(tvl_usd,observed_at)tvl_usd,last(utilization,observed_at)utilization FROM market_snapshots GROUP BY market_id,bucket WITH NO DATA;
CREATE MATERIALIZED VIEW IF NOT EXISTS cagg_market_daily WITH(timescaledb.continuous)AS SELECT market_id,time_bucket(INTERVAL'1 day',observed_at)bucket,last(supply_apr,observed_at)supply_apr,last(borrow_apr,observed_at)borrow_apr,last(fixed_apy,observed_at)fixed_apy,last(implied_apy,observed_at)implied_apy,last(liquidity_usd,observed_at)liquidity_usd,last(tvl_usd,observed_at)tvl_usd,last(utilization,observed_at)utilization FROM market_snapshots GROUP BY market_id,bucket WITH NO DATA;
SELECT add_continuous_aggregate_policy('cagg_market_hourly',start_offset=>INTERVAL'7 days',end_offset=>INTERVAL'5 minutes',schedule_interval=>INTERVAL'15 minutes',if_not_exists=>TRUE);
SELECT add_continuous_aggregate_policy('cagg_market_daily',start_offset=>INTERVAL'90 days',end_offset=>INTERVAL'1 hour',schedule_interval=>INTERVAL'1 hour',if_not_exists=>TRUE);
